    let mut p2 = string2;
    loop {
        let c1 = unsafe { tolower(*p1) };
        let c2 = unsafe { tolower(*p2) };
        if c1 != c2 {
            if c1 < c2 {
                return -1;
            } else {
                return 1;
            }
        }
        if c1 == 0 {
