pub type SortedArrayValue<T> = Option<T>;
pub struct SortedArray<T> {
    pub data: Vec<SortedArrayValue<T>>,
    pub length: u32,
    pub _alloced: u32,
    pub equ_func: SortedArrayEqualFunc<T>,
    pub cmp_func: SortedArrayCompareFunc<T>,
}

pub type SortedArrayEqualFunc<T> = fn(SortedArrayValue<T>, SortedArrayValue<T>) -> bool;
pub type SortedArrayCompareFunc<T> = fn(SortedArrayValue<T>, SortedArrayValue<T>) -> i32;

impl<T> SortedArray<T> {
    pub fn new(length: u32, equ_func: SortedArrayEqualFunc<T>, cmp_func: SortedArrayCompareFunc<T>) -> Self {
        Self {
            data: Vec::with_capacity(length as usize),
            length: 0,
            _alloced: length,
            equ_func,
            cmp_func,
        }
    }
}

pub fn sortedarray_get<T>(array: &SortedArray<T>, i: u32) -> Option<&SortedArrayValue<T>> {
    array.data.get(i as usize)
}

pub fn sortedarray_length<T>(array: &SortedArray<T>) -> u32 {
    array.length
}

pub fn sortedarray_free<T>(sortedarray: SortedArray<T>) {
    drop(sortedarray);
}

pub fn sortedarray_remove<T>(sortedarray: &mut SortedArray<T>, index: u32) {
    if index < sortedarray.length {
        sortedarray.data.remove(index as usize);
        sortedarray.length -= 1;
    }
}

pub fn sortedarray_remove_range<T>(sortedarray: &mut SortedArray<T>, index: u32, length: u32) {
    if index < sortedarray.length {
        let end = index + length;
        if end > sortedarray.length {
            sortedarray.data.drain(index as usize..);
        } else {
            sortedarray.data.drain(index as usize..end as usize);
        }
        sortedarray.length -= length.min(sortedarray.length - index);
    }
}

pub fn sortedarray_insert<T>(sortedarray: &mut SortedArray<T>, data: SortedArrayValue<T>) -> bool {
    if sortedarray.length < sortedarray._alloced {
        sortedarray.data.push(data);
        sortedarray.length += 1;
        true
    } else {
        false
    }
}

pub fn sortedarray_index_of<T>(sortedarray: &SortedArray<T>, data: SortedArrayValue<T>) -> i32 {
    for (i, value) in sortedarray.data.iter().enumerate() {
        if (sortedarray.equ_func)(*value, data) {
            return i as i32;
        }
    }
    -1
}

pub fn sortedarray_clear<T>(sortedarray: &mut SortedArray<T>) {
    sortedarray.data.clear();
    sortedarray.length = 0;
}

