static void trie_insert_rollback(Trie *trie, unsigned char *key)
{
	TrieNode *node;
	TrieNode **prev_ptr;
	TrieNode *next_node;
	TrieNode **next_prev_ptr;
	unsigned char *p;
	node = trie->root_node;
	prev_ptr = &trie->root_node;
	p = key;
	while (node != NULL) {
		next_prev_ptr = &node->next[(unsigned char) *p];
		next_node = *next_prev_ptr;
		++p;
		--node->use_count;
		if (node->use_count == 0) {
			free(node);
			if (prev_ptr != NULL) {
				*prev_ptr = NULL;
			}
			next_prev_ptr = NULL;
		}
		node = next_node;
		prev_ptr = next_prev_ptr;
	}
}

